[asy]
unitsize(0.4 cm);

pair[] A, B, C, P;
pair M;

A[1] = (3,3);
A[2] = (13,3);
A[3] = (10,0);
A[4] = (0,0);
P[1] = (A[1] + A[2])/2;
P[2] = (A[3] + A[4])/2;

B[1] = P[1] + 4*dir(-45);
B[4] = B[1] + P[2] - P[1];
B[2] = 2*P[1] - B[1];
B[3] = 2*P[2] - B[4];

C[1] = P[1] + 4*dir(75);
C[4] = C[1] + P[2] - P[1];
C[2] = 2*P[1] - C[1];
C[3] = 2*P[2] - C[4];

M = (P[1] + P[2])/2;

draw((M + 2*dir(75))--M--(M + (2,0)));
draw(P[1]--P[2]);
draw(extension(P[2],C[4],A[1],A[2])--A[1]--A[4]--A[3]--A[2]--P[1]);
draw(P[1]--C[1]--C[4]--C[3]--C[2]--extension(C[2],C[1],A[3],P[2]));

label("$\theta$", M + (1,1), UnFill);
