draw((2,0)--(2,2.5),Arrow(6));
draw(2*dir(75)--(2*dir(75) + 2.5*dir(-15)),Arrow(6));
draw(rightanglemark((0,0),(2,0),(2,2),10));
draw(rightanglemark((0,0),2*dir(75),2*dir(75) + 2*dir(-15),10));

